# 描述: SSD1306 128x64 OLED Display Controller (I2C/SPI)
# CPU架构: Display
# 位宽: 8位
# 时钟频率: 400000 Hz

module SSD1306

  # 内存段定义
  GDDRAM_START = 0x00
  GDDRAM_END = 0x3FF
  GDDRAM_SIZE = 1024  # Graphic Display Data RAM (128x64 = 1024 bytes)

  # 外设定义
  # SSD1306 128x64 OLED (0x3C/0x3D I2C, 3.3V-5V)
  SSD1306_BASE = 0x3C
  SSD1306_CMD_ADDR = 0x00
  SSD1306_DATA_ADDR = 0x40
  SSD1306_DISPLAY_OFF_ADDR = 0xAE
  SSD1306_DISPLAY_ON_ADDR = 0xAF
  SSD1306_CONTRAST_ADDR = 0x81
  SSD1306_SEG_REMAP_ADDR = 0xA1
  SSD1306_COM_SCAN_ADDR = 0xC8
  SSD1306_ADDR_MODE_ADDR = 0x20
  SSD1306_COL_START_ADDR = 0x21
  SSD1306_PAGE_START_ADDR = 0x22

end
